import numpy as np


def adam_first_step(g, lr, beta1, beta2, eps, corrected):
    g = np.asarray(g, dtype=float)
    m = (1 - beta1) * g
    v = (1 - beta2) * g * g
    if corrected:
        m = m / (1 - beta1)
        v = v / (1 - beta2)
    return lr * np.abs(m) / (np.sqrt(v) + eps)
